"It's Saturday morning.":"Es ist Samstagmorgen.",
"I want to bake a cake for Mum!":"Ich will einen Kuchen für Mama backen!",
"Can I help you?":"Kann ich dir helfen?",
"Yes! We need flour, eggs and sugar.":"Ja! Wir brauchen Mehl, Eier und Zucker.",
"Meow!":"Miau!",
"Pus, don't eat the butter!":"Pus, iss nicht die Butter!",
"Oh no! Flour all over the kitchen!":"Oh nein! Überall Mehl in der Küche!",
"The cake is ready. It's a bit crooked...":"Der Kuchen ist fertig. Er ist etwas schief …",
"But it smells so good!":"Aber er riecht so gut!",
"Thank you so much, my darlings! This is the best cake in the world!":"Vielen Dank, meine Lieben! Das ist der beste Kuchen der Welt!",
"Meow, meow!":"Miau, miau!",
"Good morning, Leo! Today is your first day at school.":"Guten Morgen, Leo! Heute ist dein erster Schultag.",
"I'm a little scared, Mum.":"Ich habe ein bisschen Angst, Mama.",
"Hi and welcome! My name is Ingrid. What's your name?":"Hallo und willkommen! Ich heiße Ingrid. Wie heißt du?",
"My name is Leo. I come from Ukraine.":"Ich heiße Leo. Ich komme aus der Ukraine.",
"Hi, Leo! Do you want to sit next to me?":"Hallo, Leo! Willst du neben mir sitzen?",
"Yes, I'd love to!":"Ja, sehr gern!",
"What is one plus two?":"Was ist eins plus zwei?",
"Three!":"Drei!",
"You're so clever!":"Du bist so klug!",
"Break time!":"Pause!",
"Come on, let's play football!":"Komm, lass uns Fußball spielen!",
"How was school?":"Wie war die Schule?",
"Super fun! Nora is my new friend!":"Super lustig! Nora ist meine neue Freundin!",
"Today we're going for a walk in the forest!":"Heute machen wir einen Spaziergang im Wald!",
"Hooray! I'll bring the basket.":"Hurra! Ich nehme den Korb mit.",
"Look, there's a mushroom!":"Schau, da ist ein Pilz!",
"That mushroom is poisonous. Don't eat it!":"Dieser Pilz ist giftig. Iss ihn nicht!",
"There are lots of blueberries here!":"Hier gibt es viele Blaubeeren!",
"Yum! They're so sweet!":"Lecker! Sie sind so süß!",
"What was that?":"Was war das?",
"A moose! It's huge!":"Ein Elch! Er ist riesig!",
"Then it starts to rain.":"Dann fängt es an zu regnen.",
"Be quiet. Now we walk home calmly.":"Sei leise. Jetzt gehen wir ruhig nach Hause.",
"Now we're going to drink hot cocoa.":"Jetzt trinken wir heißen Kakao.",
"That was a lovely walk!":"Das war ein schöner Spaziergang!",
"And we saw a real moose!":"Und wir haben einen echten Elch gesehen!",
"Mia, can you do the shopping for me?":"Mia, kannst du für mich einkaufen?",
"Yes! What do you need?":"Ja! Was brauchst du?",
"We need milk, bread and apples. Here are a hundred kroner.":"Wir brauchen Milch, Brot und Äpfel. Hier sind hundert Kronen.",
"Thanks, Mum!":"Danke, Mama!",
"Excuse me, where is the milk?":"Entschuldigung, wo ist die Milch?",
"The milk is over there, by the bread.":"Die Milch ist dort drüben, beim Brot.",
"I'll take six red apples.":"Ich nehme sechs rote Äpfel.",
"That will be eighty kroner.":"Das macht achtzig Kronen.",
"Here you go, here's a hundred.":"Bitte schön, hier sind hundert.",
"Twenty kroner change. Have a nice day!":"Zwanzig Kronen zurück. Schönen Tag noch!",
"You're so clever, Mia! Thank you so much.":"Du bist so klug, Mia! Vielen Dank.",
"That was easy!":"Das war leicht!",
"Meow! Milk?":"Miau! Milch?",
