"have said":"habe gesagt",
"I have lived in Norway for two years.":"Ich lebe seit zwei Jahren in Norwegen.",
"Have you been to Tromsø?":"Warst du in Tromsø?",
"The passive":"Das Passiv",
"The passive shows that something is done to the subject. Bli + participle for a specific event: “Huset ble bygd i 1990”. The s-passive for rules and regular actions: “Butikken åpnes klokka ni”, “Det snakkes norsk her”. After modals: “Søknaden må sendes i dag”.":"Das Passiv zeigt, dass etwas mit dem Subjekt gemacht wird. Bli + Partizip für ein bestimmtes Ereignis: “Huset ble bygd i 1990”. Das s-Passiv für Regeln und regelmäßige Handlungen: “Butikken åpnes klokka ni”, “Det snakkes norsk her”. Nach Modalverben: “Søknaden må sendes i dag”.",
"The house was built in 1990.":"Das Haus wurde 1990 gebaut.",
"The shop opens at nine.":"Der Laden öffnet um neun.",
"The application must be sent today.":"Der Antrag muss heute geschickt werden.",
"The book was written by Ibsen.":"Das Buch wurde von Ibsen geschrieben.",
"Many languages are spoken in Oslo.":"In Oslo werden viele Sprachen gesprochen.",
"The position was advertised in March.":"Die Stelle wurde im März ausgeschrieben.",
"Formal linking words":"Formale Verbindungswörter",
"For essays, letters and debates: derfor (therefore), likevel (nevertheless), dessuten (moreover), ettersom (since), selv om (although), i motsetning til (unlike), på grunn av (because of) + noun, for å (in order to) + infinitive. Derfor/likevel/dessuten at the start trigger inversion: “Derfor må vi…”.":"Für Aufsätze, Briefe und Debatten: derfor (deshalb), likevel (dennoch), dessuten (außerdem), ettersom (da), selv om (obwohl), i motsetning til (im Gegensatz zu), på grunn av (wegen) + Nomen, for å (um zu) + Infinitiv. Derfor/likevel/dessuten am Satzanfang lösen Inversion aus: „Derfor må vi…“.",
