"Thank you for inviting me to the interview.":"Vielen Dank für die Einladung zum Vorstellungsgespräch.",
"Could you tell me a little about yourself?":"Könnten Sie mir ein wenig über sich erzählen?",
"I am an engineer. I have worked in logistics for five years.":"Ich bin Ingenieur. Ich arbeite seit fünf Jahren in der Logistik.",
"Have you ever managed a team?":"Haben Sie schon einmal ein Team geleitet?",
"Yes, I have led a team of eight people in Kyiv.":"Ja, ich habe in Kyjiw ein Team mit acht Personen geleitet.",
"What are your greatest strengths?":"Was sind Ihre größten Stärken?",
"I am reliable, I learn quickly and I work well under pressure.":"Ich bin zuverlässig, lerne schnell und arbeite gut unter Druck.",
"Yes. What would a typical working day look like?":"Ja. Wie würde ein typischer Arbeitstag aussehen?",
