"Lost in the City":"Verloren in der Stadt",
"Excuse me, could you help me? I think I am lost.":"Entschuldigung, können Sie mir helfen? Ich glaube, ich habe mich verirrt.",
"Of course. Where do you want to go?":"Natürlich. Wohin möchten Sie?",
"I am looking for the city library.":"Ich suche die Stadtbibliothek.",
"Go straight on and turn left at the traffic lights.":"Gehen Sie geradeaus und biegen Sie an der Ampel links ab.",
"Then walk past the bus stop. The library is opposite the bank.":"Dann gehen Sie an der Bushaltestelle vorbei. Die Bibliothek ist gegenüber der Bank.",
"Is it far from here?":"Ist es weit von hier?",
"No, it only takes about ten minutes on foot.":"Nein, zu Fuß dauert es nur etwa zehn Minuten.",
"Great. And is there a café near the library?":"Gut. Und gibt es ein Café in der Nähe der Bibliothek?",
"Later, Ruslan took the wrong bus.":"Später nahm Ruslan den falschen Bus.",
"This bus does not go there. Get off at the next stop and cross the road.":"Dieser Bus fährt nicht dorthin. Steig an der nächsten Haltestelle aus und überquere die Straße.",
"Finally! The library is on the corner, just like you said.":"Endlich! Die Bibliothek ist an der Ecke, genau wie du gesagt hast.",
"Well done! Now you will never get lost again.":"Gut gemacht! Jetzt wirst du dich nie wieder verlaufen.",
