"Grammar in real life":"Grammatik im echten Leben",
"What is coding?":"Was ist Programmieren?",
"The school has a robot called Robo. He only follows exact commands, and the children learn that a program is commands in the right order.":"Die Schule hat einen Roboter namens Robo. Er befolgt nur genaue Befehle, und die Kinder lernen, dass ein Programm aus Befehlen in der richtigen Reihenfolge besteht.",
"Look, Nora! The school has got a robot.":"Schau, Nora! Die Schule hat einen Roboter bekommen.",
"Hi, robot! What is your name?":"Hallo, Roboter! Wie heißt du?",
"Hi! My name is Robo. I do what you tell me.":"Hallo! Ich heiße Robo. Ich mache, was ihr mir sagt.",
"Robo only understands commands. We call that programming.":"Robo versteht nur Befehle. Das nennen wir Programmieren.",
"What is a command?":"Was ist ein Befehl?",
"A command is a short instruction, for example “walk” or “turn”.":"Ein Befehl ist eine kurze Anweisung, zum Beispiel „geh“ oder „dreh dich“.",
"Robo, take two steps forward!":"Robo, geh zwei Schritte vorwärts!",
"Walking. One, two. Done!":"Ich gehe. Eins, zwei. Fertig!",
"Robo, make me a pizza!":"Robo, mach mir eine Pizza!",
"Error! I do not know the command “pizza”.":"Fehler! Ich kenne den Befehl „Pizza“ nicht.",
"A program is many commands in the right order.":"Ein Programm sind viele Befehle in der richtigen Reihenfolge.",
"So we have to think step by step!":"Also müssen wir Schritt für Schritt denken!",
"I want to learn to code!":"Ich will programmieren lernen!",
"And I want to learn to make pizza.":"Und ich will lernen, Pizza zu machen.",
"a robot":"ein Roboter",
"programming, coding":"Programmieren",
"to code":"programmieren",
"a command":"ein Befehl",
"a program":"ein Programm",
"a message, an instruction":"eine Nachricht, eine Anweisung",
"to understand":"verstehen",
"forward":"vorwärts",
"to turn":"sich drehen",
"done, finished":"fertig",
"error; wrong":"Fehler; falsch",
"to know":"kennen, wissen",
"an order, a sequence":"eine Reihenfolge",
"right, correct":"richtig",
"step by step":"Schritt für Schritt",
"The sandwich algorithm":"Der Sandwich-Algorithmus",
"Leo teaches Robo the robot to make a sandwich. Robo does everything literally, so Leo learns that an algorithm must be exact and in the right order.":"Leo bringt dem Roboter Robo bei, ein Sandwich zu machen. Robo nimmt alles wörtlich, und so lernt Leo, dass ein Algorithmus genau und in der richtigen Reihenfolge sein muss.",
"Dad, I am going to teach Robo to make a sandwich.":"Papa, ich bringe Robo bei, ein Sandwich zu machen.",
"Then you need an algorithm.":"Dann brauchst du einen Algorithmus.",
"What is an algorithm?":"Was ist ein Algorithmus?",
"An algorithm is like a recipe: step by step, in the right order.":"Ein Algorithmus ist wie ein Rezept: Schritt für Schritt, in der richtigen Reihenfolge.",
"Step one: Take the bread. Step two: Put on butter.":"Schritt eins: Nimm das Brot. Schritt zwei: Butter drauf.",
"Butter on … the table? Done!":"Butter auf … den Tisch? Erledigt!",
"Ha ha! You have to say exactly what Robo should do.":"Haha! Du musst genau sagen, was Robo tun soll.",
"New step two: Put butter on the slice of bread!":"Neuer Schritt zwei: Streich Butter auf die Brotscheibe!",
"Step three: Put on cheese. Step four: Give the sandwich to Leo.":"Schritt drei: Leg Käse drauf. Schritt vier: Gib Leo das Sandwich.",
"Done! Here you are.":"Erledigt! Bitte schön.",
"Mmm! The algorithm works!":"Mmm! Der Algorithmus funktioniert!",
"And remember: the order is important. First butter, then cheese.":"Und denk dran: Die Reihenfolge ist wichtig. Erst Butter, dann Käse.",
"an algorithm":"ein Algorithmus",
"a slice of bread, a sandwich":"eine Brotscheibe, ein Sandwich",
"a cheese":"ein Käse",
"to put on":"drauflegen",
"done, carried out":"erledigt, ausgeführt",
"important":"wichtig",
"then":"dann",
"Repeat! Robo dances":"Wiederhole! Robo tanzt",
"Nora wants Robo to dance, but there are too many commands. The teacher shows a loop: “repeat 4 times” — and the program becomes short.":"Nora will, dass Robo tanzt, aber es sind zu viele Befehle. Die Lehrerin zeigt eine Schleife: „wiederhole 4-mal“ – und das Programm wird kurz.",
"Robo, jump! Clap! Jump! Clap! Jump! Clap!":"Robo, spring! Klatsch! Spring! Klatsch! Spring! Klatsch!",
"Jump. Clap. Jump. Clap …":"Sprung. Klatschen. Sprung. Klatschen …",
"Phew, that is a lot to write.":"Puh, das ist viel zu schreiben.",
"Use a loop! A loop repeats commands.":"Nimm eine Schleife! Eine Schleife wiederholt Befehle.",
"Write: repeat four times: jump and clap.":"Schreib: wiederhole viermal: springen und klatschen.",
"So short!":"So kurz!",
"Jump, clap! Jump, clap! Jump, clap! Jump, clap!":"Spring, klatsch! Spring, klatsch! Spring, klatsch! Spring, klatsch!",
"Robo is dancing!":"Robo tanzt!",
"Can we repeat it a hundred times?":"Können wir es hundertmal wiederholen?",
"Yes. Computers never get tired.":"Ja. Computer werden nie müde.",
"But Robo is getting dizzy …":"Aber Robo wird schwindelig …",
"Ha ha! We are stopping the loop now.":"Haha! Wir stoppen jetzt die Schleife.",
"a loop":"eine Schleife",
