"a hundred":"hundert",
"to stop":"stoppen",
"If it rains …":"Wenn es regnet …",
"Robo does not know when to take an umbrella. Leo and Mum write him a rule: if it rains — an umbrella, otherwise — sunglasses.":"Robo weiß nicht, wann er einen Regenschirm mitnehmen soll. Leo und Mama schreiben ihm eine Regel: Wenn es regnet – Regenschirm, sonst – Sonnenbrille.",
"Robo, we are going out. Bring an umbrella.":"Robo, wir gehen raus. Nimm einen Regenschirm mit.",
"Why? The sun is shining.":"Warum? Die Sonne scheint.",
"You are right, Robo. We need a rule.":"Du hast recht, Robo. Wir brauchen eine Regel.",
"If it rains, we take an umbrella.":"Wenn es regnet, nehmen wir einen Regenschirm.",
"If it rains, then we take an umbrella. Otherwise we take sunglasses.":"Wenn es regnet, dann nehmen wir einen Regenschirm. Sonst nehmen wir eine Sonnenbrille.",
"If … then … otherwise. Understood!":"Wenn … dann … sonst. Verstanden!",
"It is raining. I am taking the umbrella.":"Es regnet. Ich nehme den Regenschirm.",
"Good, Robo!":"Gut, Robo!",
"Now the sun is shining. I am taking sunglasses.":"Jetzt scheint die Sonne. Ich nehme die Sonnenbrille.",
"Robo thinks like a computer.":"Robo denkt wie ein Computer.",
"If I tidy my room, then I get ice cream?":"Wenn ich mein Zimmer aufräume, bekomme ich dann ein Eis?",
"Yes! That is a good rule.":"Ja! Das ist eine gute Regel.",
"otherwise, else":"sonst",
"an umbrella":"ein Regenschirm",
"sunglasses":"eine Sonnenbrille",
"the sun is shining":"die Sonne scheint",
"to go out":"rausgehen",
"to bring":"mitnehmen",
"to be right":"recht haben",
"understood":"verstanden",
"to think":"denken",
"Points in the box":"Punkte in der Kiste",
"Nora and Leo make a game: a cat catches fish and gets points. The teacher explains a variable — a box with a name where the computer keeps a number.":"Nora und Leo machen ein Spiel: Eine Katze fängt Fische und bekommt Punkte. Die Lehrerin erklärt eine Variable – eine Kiste mit Namen, in der der Computer eine Zahl aufbewahrt.",
"We are making a game! Every time the cat catches a fish, we get a point.":"Wir machen ein Spiel! Jedes Mal, wenn die Katze einen Fisch fängt, bekommen wir einen Punkt.",
"But where will the computer remember the points?":"Aber wo merkt sich der Computer die Punkte?",
"In a variable. A variable is like a box with a name.":"In einer Variable. Eine Variable ist wie eine Kiste mit einem Namen.",
"The box is called “points”. Right now there is zero in the box.":"Die Kiste heißt „Punkte“. Gerade ist eine Null in der Kiste.",
"The cat catches a fish!":"Die Katze fängt einen Fisch!",
"Then we write: points equals points plus one.":"Dann schreiben wir: Punkte gleich Punkte plus eins.",
"Points is one. Points is two. Points is three!":"Punkte ist eins. Punkte ist zwei. Punkte ist drei!",
"The value in the box changes!":"Der Wert in der Kiste ändert sich!",
"Can we have more boxes?":"Können wir mehr Kisten haben?",
"Yes. Name, lives and speed … A game has many variables.":"Ja. Name, Leben und Tempo … Ein Spiel hat viele Variablen.",
"We have ten points! We won!":"Wir haben zehn Punkte! Wir haben gewonnen!",
"The variable “joy” is now a hundred.":"Die Variable „Freude“ ist jetzt hundert.",
"a point":"ein Punkt",
