"a joy":"eine Freude",
"to keep, to take care of":"aufbewahren, sich kümmern um",
"Find the bug!":"Finde den Fehler!",
"Robo has to reach the star but walks into a wall. The children read the program line by line, find the bug and fix it.":"Robo soll zum Stern gehen, läuft aber gegen eine Wand. Die Kinder lesen das Programm Zeile für Zeile, finden den Fehler und beheben ihn.",
"Robo has to walk to the star. I have written the program.":"Robo soll zum Stern gehen. Ich habe das Programm geschrieben.",
"I am starting the program now.":"Ich starte jetzt das Programm.",
"Ouch! I walked straight into the wall.":"Autsch! Ich bin direkt gegen die Wand gelaufen.",
"Oops! The program has a bug.":"Hoppla! Das Programm hat einen Fehler.",
"We call an error in a program a bug.":"Einen Fehler in einem Programm nennen wir Bug.",
"Finding and fixing the error is called debugging.":"Den Fehler zu finden und zu beheben, nennt man Debugging.",
"We read the program line by line: forward, forward, right …":"Wir lesen das Programm Zeile für Zeile: vorwärts, vorwärts, rechts …",
"There! It should say left, not right.":"Da! Da muss links stehen, nicht rechts.",
"Now I will fix the bug and try again.":"Jetzt behebe ich den Fehler und versuche es noch mal.",
"I am at the star! The program works.":"Ich bin beim Stern! Das Programm funktioniert.",
"All programmers make mistakes. The important thing is to try again.":"Alle Programmierer machen Fehler. Wichtig ist, es noch mal zu versuchen.",
"Mistakes are part of learning!":"Fehler gehören zum Lernen dazu!",
