"Which language?":"Welche Sprache?",
"Leo asks Robo which language he speaks. The teacher explains programming languages: Scratch, Python, JavaScript, HTML and CSS, Swift, Kotlin and C#.":"Leo fragt Robo, welche Sprache er spricht. Die Lehrerin erklärt Programmiersprachen: Scratch, Python, JavaScript, HTML und CSS, Swift, Kotlin und C#.",
"Robo, which language do you speak? Norwegian?":"Robo, welche Sprache sprichst du? Norwegisch?",
"I understand programming languages. There are many!":"Ich verstehe Programmiersprachen. Es gibt viele!",
"Children often start with Scratch. There we move colourful blocks.":"Kinder fangen oft mit Scratch an. Dort verschieben wir bunte Blöcke.",
"It looks like Lego!":"Das sieht aus wie Lego!",
"Python is easy to read. It is used for games, data and artificial intelligence.":"Python ist leicht zu lesen. Man benutzt es für Spiele, Daten und künstliche Intelligenz.",
"Artificial intelligence? Like Robo?":"Künstliche Intelligenz? Wie Robo?",
"HTML builds web pages, and CSS makes them pretty. JavaScript makes them move.":"HTML baut Webseiten, und CSS macht sie schön. JavaScript bringt sie in Bewegung.",
"So the school website is made with them?":"Also ist die Schulwebseite damit gemacht?",
"We make iPhone apps with Swift, and Android apps with Kotlin.":"iPhone-Apps machen wir mit Swift und Android-Apps mit Kotlin.",
"And games?":"Und Spiele?",
"Many games are made with C#.":"Viele Spiele werden mit C# gemacht.",
"Which language should I learn first?":"Welche Sprache soll ich zuerst lernen?",
"Start with Scratch or Python. The most important thing is to think logically.":"Fang mit Scratch oder Python an. Am wichtigsten ist es, logisch zu denken.",
"a programming language":"eine Programmiersprache",
"to exist":"existieren, es gibt",
"colourful":"bunt",
"a block":"ein Block",
"simple, easy":"einfach",
"artificial intelligence":"künstliche Intelligenz",
"data":"Daten",
"a web page, a website":"eine Webseite",
"logically":"logisch",
"the most important thing":"das Wichtigste",
"A model of the school":"Ein Modell der Schule",
"The class makes a model of the schoolyard. The children learn that a model is a simple copy, that things in a program have properties, and that you draw the plan before the code.":"Die Klasse baut ein Modell des Schulhofs. Die Kinder lernen, dass ein Modell eine einfache Kopie ist, dass Dinge in einem Programm Eigenschaften haben und dass man den Plan vor dem Code zeichnet.",
"Today we are making a model of the schoolyard.":"Heute bauen wir ein Modell des Schulhofs.",
"What is a model?":"Was ist ein Modell?",
"A model is a simple copy of something real. A map is a model too.":"Ein Modell ist eine einfache Kopie von etwas Echtem. Eine Karte ist auch ein Modell.",
"Like the map in a game!":"Wie die Karte in einem Spiel!",
"We only draw the important things: the school, the gate and the football pitch.":"Wir zeichnen nur das Wichtige: die Schule, das Tor und den Fußballplatz.",
"We do not need to draw every single leaf.":"Wir müssen nicht jedes einzelne Blatt zeichnen.",
"In a program we describe things with properties. A ball has a colour, a size and a speed.":"In einem Programm beschreiben wir Dinge mit Eigenschaften. Ein Ball hat eine Farbe, eine Größe und ein Tempo.",
"So the ball is white and fast!":"Also ist der Ball weiß und schnell!",
"And a flowchart shows what happens, step by step.":"Und ein Flussdiagramm zeigt, was passiert, Schritt für Schritt.",
"First we draw the plan, then we write the code.":"Erst zeichnen wir den Plan, dann schreiben wir den Code.",
"I have made a model of Leo: hungry, happy and likes football.":"Ich habe ein Modell von Leo gemacht: hungrig, fröhlich und mag Fußball.",
"Ha ha! That is right!":"Haha! Das stimmt!",
