"that is right":"das stimmt",
"A website for Pus: HTML basics":"Eine Webseite für Pus: HTML-Grundlagen",
"Nora and Leo make a website about Pus the cat. Robo explains HTML: tags in angle brackets, a heading <h1>, a paragraph <p>, an image <img> and a link <a>.":"Nora und Leo machen eine Webseite über die Katze Pus. Robo erklärt HTML: Tags in spitzen Klammern, eine Überschrift <h1>, einen Absatz <p>, ein Bild <img> und einen Link <a>.",
"I want to make a website about our cat, Pus!":"Ich will eine Webseite über unsere Katze Pus machen!",
"Then we need HTML.":"Dann brauchen wir HTML.",
"HTML builds web pages. It is made of tags.":"HTML baut Webseiten. Es besteht aus Tags.",
"What is a tag?":"Was ist ein Tag?",
"A tag is a short word in angle brackets, for example p.":"Ein Tag ist ein kurzes Wort in spitzen Klammern, zum Beispiel p.",
"Most tags have a start and an end. The end tag has a slash.":"Die meisten Tags haben einen Anfang und ein Ende. Das End-Tag hat einen Schrägstrich.",
"Like a sandwich!":"Wie ein Sandwich!",
"I write h1 and “Pus”. It becomes a big heading!":"Ich schreibe h1 und „Pus“. Das wird eine große Überschrift!",
"Yes. h1 means heading number one.":"Ja. h1 bedeutet Überschrift Nummer eins.",
"With p we make a paragraph, and with img we show a picture.":"Mit p machen wir einen Absatz, und mit img zeigen wir ein Bild.",
"Look, a picture of Pus!":"Schau, ein Bild von Pus!",
"Finally a link. The a tag takes us to another page.":"Zum Schluss ein Link. Das a-Tag bringt uns auf eine andere Seite.",
"The website is ready! Next time we will make it pretty with CSS.":"Die Webseite ist fertig! Nächstes Mal machen wir sie mit CSS schön.",
"a website, a web page":"eine Webseite",
